package com.chocohead.gravisuite.audit;
import com.chocohead.gravisuite.*;
import ic2.api.item.*;
import net.minecraft.core.*;
import net.minecraft.core.registries.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.item.*;
import net.minecraft.world.item.crafting.*;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
import net.neoforged.neoforge.common.util.FakePlayerFactory;
import com.google.gson.*;
import java.io.*;
import java.util.*;
@EventBusSubscriber(modid=Gravisuite.MODID)
public final class ServerAudit {
 private static int checks,failed;
 public static void check(String name,boolean ok,Object detail){checks++;if(!ok)failed++;Gravisuite.LOG.info("[gravisuite-audit] {} {} {}",ok?"PASS":"FAIL",name,detail);}
 private static ItemStack item(String id){return new ItemStack(BuiltInRegistries.ITEM.get(ResourceLocation.parse(id)));}
 @SubscribeEvent static void start(ServerStartedEvent event){if("config".equals(System.getProperty("gravisuite.audit"))){var recipes=event.getServer().getRecipeManager().getAllRecipesFor(RecipeType.CRAFTING).stream().filter(h->h.id().getNamespace().equals("gravisuite")).toList();if(recipes.size()!=4||recipes.stream().anyMatch(h->h.id().getPath().contains("lappack")||h.id().getPath().equals("magnetron")||h.id().getPath().equals("vajra_core")||h.id().getPath().equals("engine_booster")))throw new IllegalStateException("Disabled Gravi recipe leaked: "+recipes);Gravisuite.LOG.info("[gravisuite-config-audit] DONE PASS only4ungatedcomponentrecipes");event.getServer().halt(false);return;}if(!"server".equals(System.getProperty("gravisuite.audit")))return;var l=event.getServer().overworld();var fake=FakePlayerFactory.getMinecraft(l);fake.getInventory().clearContent();for(var slot:EquipmentSlot.values())fake.setItemSlot(slot,ItemStack.EMPTY);
  check("seven original crafting components",GraviItems.COMPONENTS.size()==7,GraviItems.COMPONENTS.keySet());
  for(String name:List.of("advanced_lappack","ultimate_lappack")){boolean advanced=name.startsWith("advanced");var stack=item("gravisuite:"+name);var api=(IElectricItem)stack.getItem();check(name+" original capacity/tier/transfer/provider",api.getMaxCharge(stack)==(advanced?3e6:6e7)&&api.getTier(stack)==(advanced?3:4)&&api.getTransferLimit(stack)==(advanced?30000:100000)&&api.canProvideEnergy(stack),api.getMaxCharge(stack));check(name+" lower-tier charging refused",ElectricItem.manager.charge(stack,10000,api.getTier(stack)-1,true,false)==0,ElectricItem.manager.getCharge(stack));check(name+" transfer limit respected",ElectricItem.manager.charge(stack,1e9,4,false,false)==api.getTransferLimit(stack),ElectricItem.manager.getCharge(stack));ElectricItem.manager.charge(stack,Double.POSITIVE_INFINITY,4,true,false);check(name+" capacity clamp",ElectricItem.manager.getCharge(stack)==api.getMaxCharge(stack),ElectricItem.manager.getCharge(stack));var encoded=stack.save(l.registryAccess());var decoded=ItemStack.parseOptional(l.registryAccess(),(net.minecraft.nbt.CompoundTag)encoded);check(name+" EU survives native item save/load",ElectricItem.manager.getCharge(decoded)==api.getMaxCharge(stack),ElectricItem.manager.getCharge(decoded));fake.setItemSlot(EquipmentSlot.CHEST,stack);var drill=item("ic2:diamond_drill");ElectricItem.manager.chargeFromArmor(drill,fake);check(name+" powers native IC2 drill",ElectricItem.manager.getCharge(drill)==30000&&ElectricItem.manager.getCharge(stack)==api.getMaxCharge(stack)-30000,ElectricItem.manager.getCharge(drill));check(name+" native mining consumes EU from pack",ElectricItem.manager.use(drill,80,fake)&&ElectricItem.manager.getCharge(drill)==30000&&ElectricItem.manager.getCharge(stack)==api.getMaxCharge(stack)-30080,ElectricItem.manager.getCharge(stack));var quantum=item("ic2:quantum_chestplate");ElectricItem.manager.chargeFromArmor(quantum,fake);check(name+" output tier enforced on quantum armor",advanced?ElectricItem.manager.getCharge(quantum)==0:ElectricItem.manager.getCharge(quantum)==1e7,ElectricItem.manager.getCharge(quantum));fake.setItemSlot(EquipmentSlot.CHEST,ItemStack.EMPTY);}
  for(var holder:l.getRecipeManager().getAllRecipesFor(RecipeType.CRAFTING)){if(!holder.id().getNamespace().equals("gravisuite"))continue;var recipe=holder.value();var shaped=(ShapedRecipe)recipe;var grid=new ArrayList<ItemStack>();for(var ingredient:recipe.getIngredients()){var choices=ingredient.getItems();check(holder.id()+" ingredient resolves",ingredient.isEmpty()||choices.length>0,choices.length);var in=choices.length==0?ItemStack.EMPTY:choices[0].copy();if(in.getItem() instanceof IElectricItem)ElectricItem.manager.charge(in,1234,4,true,false);grid.add(in);}var input=CraftingInput.of(shaped.getWidth(),shaped.getHeight(),grid);check(holder.id()+" matches native crafting",recipe.matches(input,l),input.size());var output=recipe.assemble(input,l.registryAccess());double charge=grid.stream().mapToDouble(ElectricItem.manager::getCharge).sum();check(holder.id()+" original EU sum/output count",ElectricItem.manager.getCharge(output)==(output.getItem() instanceof IElectricItem api?Math.min(charge,api.getMaxCharge(output)):0)&&output.getCount()==recipe.getResultItem(l.registryAccess()).getCount(),output);}
  ToolAudit.run(l,fake,null);check("all fourteen original component/pack/tool recipes",l.getRecipeManager().getAllRecipesFor(RecipeType.CRAFTING).stream().filter(h->h.id().getNamespace().equals("gravisuite")).count()==14,"14");fake.getInventory().clearContent();Gravisuite.LOG.info("[gravisuite-audit] DONE {} checks, {} failed",checks,failed);event.getServer().halt(false);
 }
}
